#[derive(Debug)]
struct Account {
    username: String,
    balance: f64,
}

impl Account {
    // 关联函数 (构造器)
    fn new(username: &str, initial: f64) -> Self {
        Self { username: username.to_string(), balance: initial }
    }
    // 方法 (&mut self)
    fn deposit(&mut self, amount: f64) {
        self.balance += amount;
    }
}

fn main() {
    let mut acc = Account::new("Alice", 100.0);
    acc.deposit(50.0);
    println!("{:?}", acc);
}

#[derive(Debug)]
enum WebEvent {
    PageLoad,
    KeyPress(char),
    Click { x: i64, y: i64 },
}

fn inspect(event: WebEvent) {
    match event {
        WebEvent::PageLoad => println!("Page loaded"),
        WebEvent::KeyPress(c) => println!("Pressed key: {}", c),
        WebEvent::Click { x, y } if x > 0 && y > 0 => println!("Quadrant 1 click: ({}, {})", x, y),
        WebEvent::Click { x, y } => println!("Click: ({}, {})", x, y),
    }
}

fn main() {
    inspect(WebEvent::Click { x: 10, y: 20 });
}

