fn main() {
    let numbers = vec![1, 2, 3, 4, 5, 6];
    // 惰性流水线：筛选偶数 -> 平方 -> 求和
    let sum_of_even_squares: i32 = numbers.iter()
        .filter(|&&x| x % 2 == 0)
        .map(|&x| x * x)
        .sum();
    println!("偶数平方和: {}", sum_of_even_squares); // 2^2 + 4^2 + 6^2 = 56
}

