use std::sync::Arc;
use std::thread;

fn main() {
    let data = Arc::new(vec![1, 2, 3]);
    let data_clone = Arc::clone(&data); // 增加原子计数

    let handle = thread::spawn(move || {
        println!("子线程读取数据: {:?}", data_clone);
    });

    handle.join().unwrap();
    println!("主线程引用计数: {}", Arc::strong_count(&data));
}

