use std::sync::mpsc;
use std::thread;

fn main() {
    let (tx, rx) = mpsc::channel();
    let tx1 = tx.clone(); // 克隆出多个生产者

    thread::spawn(move || { tx1.send("来自工作线程 1").unwrap(); });
    thread::spawn(move || { tx.send("来自工作线程 2").unwrap(); });

    for msg in rx.iter().take(2) {
        println!("主线程收到: {}", msg);
    }
}

use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let counter = Arc::new(Mutex::new(0));
    let mut handles = vec![];

    for _ in 0..10 {
        let counter_clone = Arc::clone(&counter);
        let handle = thread::spawn(move || {
            let mut num = counter_clone.lock().unwrap(); // 自动加锁
            *num += 1;
        }); // 离开作用域自动释放锁
        handles.push(handle);
    }

    for h in handles { h.join().unwrap(); }
    println!("累加结果: {}", *counter.lock().unwrap()); // 10
}

